const schoolRows=new Map(rows.split('\n').map(r=>{const[n,...q]=r.split('|');return[n,q];}));
export function makeInstitutionQuiz(row,evidence){const[q,a,b,c]=row,offset=[...q].reduce((n,s)=>n+s.charCodeAt(0),0)%3,options=[a,b,c];return{question:q,options:offset?options.slice(-offset).concat(options.slice(0,-offset)):options,answer:offset,hint:evidence,explain:a+'! 이 기관만의 역사와 특징을 기억해 보자.'};}
export function schoolQuiz(s){const row=schoolRows.get(s.name);if(!row)throw Error('Missing school quiz: '+s.name);return makeInstitutionQuiz(row,s.history+' '+s.distinctiveFeature);}
