export function officeQuiz(p,d){const row=officeRows[p.name==='홍성군청'?p.name:p.area.replace('홍성군 ','')];return makeInstitutionQuiz([p.name+'에서 배워요: '+row[0],...row.slice(1)],p.name==='홍성군청'?'1914년 홍주군과 결성군을 합쳐 홍성군이 되었어.':d.history+' '+d.feature);}
export function enrichOtherInstitutions(places){const special={
 '홍북읍 주민복합지원센터':['홍북읍 주민복합지원센터 같은 복합시설의 장점은?','여러 생활 서비스를 한곳에서 이용해요','기차만 탈 수 있어요','물건만 보관해요'],
 '충청남도 교육청':['충청남도 교육청이 주로 돕는 분야는?','충남의 학교 교육과 학생들의 배움','바다의 여객선 운항','토굴새우젓 판매'],
 '홍성교육지원청':['홍성교육지원청과 학교를 연결해 생각하면?','지역 학교의 교육활동을 지원해요','홍성역 열차를 운전해요','남당항 배를 수리해요']};for(const p of places)if(special[p.name]){const row=special[p.name];p.pages.push(row[1]+'. 기관마다 맡은 일이 어떻게 다른지 비교해 보자.');p.quiz=makeInstitutionQuiz(row,p.pages.map(s=>s.replace(/<[^>]+>/g,'')).join(' '));}}
